// Package ai is the HTTP client for the Python AI service (ai-service/).
package ai

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// maxResponseBytes limits the AI service response size (1 MB).
const maxResponseBytes = 1 << 20

// Sentinel errors. Callers check them with errors.Is.
var (
	ErrUnavailable = errors.New("ai service unavailable")
	ErrTimeout     = errors.New("ai service timed out")
)

// Enrichment is the card content generated by the AI service.
type Enrichment struct {
	Translation string `json:"translation"`
	Example     string `json:"example"`
	ITContext   string `json:"it_context"`
}

// Client calls the AI service over HTTP.
type Client struct {
	baseURL string
	timeout time.Duration
	http    *http.Client
}

// NewClient creates a Client for the AI service at baseURL,
// for example "http://localhost:8000". Every call is limited by timeout.
func NewClient(baseURL string, timeout time.Duration) *Client {
	return &Client{
		baseURL: strings.TrimRight(baseURL, "/"),
		timeout: timeout,
		// No http.Client.Timeout: the context deadline in Enrich limits the call,
		// and it also stops when the caller's request is cancelled.
		http: &http.Client{},
	}
}

// Enrich asks the AI service for a translation, an example and an IT context
// for phrase. It returns ErrTimeout if the call takes longer than the client
// timeout or the caller's deadline, and ErrUnavailable for any other failure.
func (c *Client) Enrich(ctx context.Context, phrase string) (Enrichment, error) {
	ctx, cancel := context.WithTimeout(ctx, c.timeout)
	defer cancel()

	body, err := json.Marshal(map[string]string{"phrase": phrase})
	if err != nil {
		return Enrichment{}, fmt.Errorf("encode enrich request: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/enrich", bytes.NewReader(body))
	if err != nil {
		return Enrichment{}, fmt.Errorf("build enrich request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")

	resp, err := c.http.Do(req)
	if err != nil {
		return Enrichment{}, callError(ctx, err)
	}
	// A Close error on a response body we have already read changes nothing.
	defer func() { _ = resp.Body.Close() }()

	switch {
	case resp.StatusCode == http.StatusGatewayTimeout: // the LLM behind the AI service timed out
		return Enrichment{}, fmt.Errorf("%w: status %d", ErrTimeout, resp.StatusCode)
	case resp.StatusCode != http.StatusOK:
		return Enrichment{}, fmt.Errorf("%w: status %d", ErrUnavailable, resp.StatusCode)
	}

	// Read one byte over the limit: that is how a too large body is detected.
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
	if err != nil {
		// The deadline can also expire while the body is being read.
		return Enrichment{}, callError(ctx, fmt.Errorf("read enrich response: %w", err))
	}
	if len(data) > maxResponseBytes {
		return Enrichment{}, fmt.Errorf("%w: response is larger than %d bytes", ErrUnavailable, maxResponseBytes)
	}

	// Unmarshal, not Decoder.Decode: Decode stops after the first JSON value
	// and ignores anything after it, Unmarshal rejects such a body.
	var e Enrichment
	if err := json.Unmarshal(data, &e); err != nil {
		return Enrichment{}, fmt.Errorf("%w: decode enrich response: %w", ErrUnavailable, err)
	}
	// The AI service validates this too, but the Go API must not save empty
	// content if the contract changes on the other side.
	if strings.TrimSpace(e.Example) == "" || strings.TrimSpace(e.ITContext) == "" {
		return Enrichment{}, fmt.Errorf("%w: empty example or it_context", ErrUnavailable)
	}
	return e, nil
}

// callError classifies a failed call. It checks ctx, not err: net/http wraps
// a context error in different ways, but ctx.Err() is always reliable.
func callError(ctx context.Context, err error) error {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return fmt.Errorf("%w: %w", ErrTimeout, err)
	}
	return fmt.Errorf("%w: %w", ErrUnavailable, err)
}
